INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/jiuwudaishi-100-june-arrivals/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002435；EPUB电子本，纸本及异文待核", "id": "31f5f807-cf99-512a-bfd0-515a744a415a"}, {"title": "辽史·卷76·张砺传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7d3fe25/content/books/zizhi-tongjian/vol-281/year-0937/part-02/sources/library/liaoshi-076-zhang-li/source.txt", "note": "《辽史》卷76·张砺传，段落 liaoshi-7cd182a20e67-p005119；已核上下文及传主，纸本及异文待核。", "id": "36f6b4da-d6d1-52e8-81a9-d5a8aef7457e"}, {"title": "宋史·巻二百四十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/songshi-249-wei-renpu-return/source.txt", "note": "《宋史》巻二百四十九，段落 songshi-9c6e46fee832-p057133；EPUB电子本，纸本及异文待核", "id": "965b1169-7b5e-564f-a005-77232b313aac"}, {"title": "宋史·巻二百四十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/songshi-249-wei-renpu-troops/source.txt", "note": "《宋史》巻二百四十九，段落 songshi-9c6e46fee832-p057134；EPUB电子本，纸本及异文待核", "id": "d50f8275-7071-566b-bc07-0c723abda098"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/xinwudaishi-067-qian-zong-succession/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003375；EPUB电子本，纸本及异文待核", "id": "6bc7a35e-fa90-5b15-8ce4-7a044f9b0446"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/xinwudaishi-067-qian-zuo-death/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003374；EPUB电子本，纸本及异文待核", "id": "6bbaff11-462a-5061-9582-2cd4d9fe0471"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb7c4e8e14cca0f06693158578b4b0287925c9b1/content/books/zizhi-tongjian/vol-287/year-0947/part-02/sources/library/tongjian-287-947-jinzhou-north-return/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003406；电子底本待考，分段待核", "id": "b4721b35-1a13-5f3c-903a-56c304cad0e9"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/jiuwudaishi-100-may-march/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002434；EPUB电子本，纸本及异文待核", "id": "e8f35e00-113d-5b0f-b315-5fbfb97263d9"}, {"title": "旧五代史·卷五十一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-051-li-congyi/source.txt", "note": "《旧五代史》卷五十一，段落 jiu-wudaishi-205deb4a7860-p001387；EPUB电子本，纸本及异文待核", "id": "7ff2a823-7208-54e1-a2ef-e7ec344ed66c"}]'::jsonb)
