INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李从朗", "aliases": ["李從朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年担任绛州刺史，起初与契丹将成霸卿等拒绝归附刘知远，五月戊申举城投降。生卒年未载。", "biography": null, "status": "draft", "id": "f8617d9b-13ea-51d5-837d-6c1907584f99"}, {"name": "成霸卿", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年被派驻绛州，与刺史李从朗等拒绝归附刘知远，后绛州归降。生卒年未载。", "biography": null, "status": "draft", "id": "748f0f81-1f2e-5ec3-a869-5e1c584f8fa7"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "薛琼", "aliases": ["薛瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年以偏将身份，在绛州归降后获任防御使。生卒年未载。", "biography": null, "status": "draft", "id": "613c3e0f-931e-5c3d-b563-b7a40d8428c9"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "萧翰", "aliases": ["蕭翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。946年十一月条下记他与通事刘重进带兵绕到晋军后方，截断粮道及归路，进至栾城接受驻军投降。《资治通鉴》称他是契丹主耶律德光的舅舅，《辽史》保存了不同的亲属说法并质疑相关姓名起源说；具体亲属关系暂待核对。生卒年本批未核。", "biography": null, "status": "draft", "id": "defe15da-7bbc-56ed-9d88-0ec31a88fcaf"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "赵远", "aliases": ["趙遠", "赵上交", "趙上交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵远，六军判官、司谏郎中、谏者。", "biography": null, "status": "draft", "id": "cb4acc0b-f3ec-52fa-9349-c01b93a95023"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "李从益", "aliases": ["李從益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李从益，获许王爵者。", "biography": null, "status": "draft", "id": "2d5dc982-595f-53af-8762-1255e0d9723d"}, {"name": "王淑妃", "aliases": ["花见羞", "花見羞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王淑妃，为求出所借宫中渠道。", "biography": null, "status": "draft", "id": "db6392e5-1b9a-5a9d-a338-bcfe97719238"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
